 const dirtyEditors=new WeakSet();document.addEventListener('input',e=>{const editor=e.target.closest?.('[contenteditable="true"]');if(editor&&e.isTrusted)dirtyEditors.add(editor)},true);const originals=new WeakMap();const attributes=new WeakMap();let locale=document.documentElement.dataset.locale==='en'?'en':'zh';let observer;const cache=new Map();
